const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mountIsaPoint = ee.Geometry.Point([139.49, -20.73]); // Lon, Lat
  const townsvillePoint = ee.Geometry.Point([146.82, -19.26]); // Lon, Lat
  const regionRadius = 20000; // 20 km radius

  const mountIsaRegion = mountIsaPoint.buffer(regionRadius);
  const townsvilleRegion = townsvillePoint.buffer(regionRadius);

  const startDate = '2019-01-27';
  const endDate = '2019-02-10';
  const thresholdCm = 65;
  const thresholdMm = thresholdCm * 10; // Convert cm to mm

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('GPM/IMERG/V06').filterDate(startDate, endDate);

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Empty Collection: No GPM images found for the specified date range.");
    console.log("A"); // C1
    return;
  }

  // 3. Processing
  // GPM provides precipitation in mm/hr. Each image is a half-hour observation.
  // To get total precipitation, we sum all half-hourly images.
  // Sum(mm/hr) * 0.5 (hr/image) = Total mm
  const precipTotalImage = collection.select('precipitationCal').sum().multiply(0.5);

  // 4. Calculation
  const getPrecipStats = (region, name) => {
    const stats = precipTotalImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 10000, // GPM native resolution is ~10km
      maxPixels: 1e9,
      bestEffort: true
    });
    return ee.Dictionary(stats);
  };

  const mountIsaStats = getPrecipStats(mountIsaRegion, 'Mount Isa').getInfo();
  const townsvilleStats = getPrecipStats(townsvilleRegion, 'Townsville').getInfo();

  // 5. Validation & Final Answer
  const mountIsaPrecip = mountIsaStats['precipitationCal_mean'];
  const mountIsaPixels = mountIsaStats['precipitationCal_count'];
  const townsvillePrecip = townsvilleStats['precipitationCal_mean'];
  const townsvillePixels = townsvilleStats['precipitationCal_count'];

  console.log(`Image collection size: ${collectionSize}`);
  console.log(`Mount Isa region valid pixels: ${mountIsaPixels}`);
  console.log(`Townsville region valid pixels: ${townsvillePixels}`);

  if (mountIsaPixels === 0 || townsvillePixels === 0) {
    console.log("No valid pixels found in one or both regions after processing.");
    console.log("C2");
    return;
  }

  if (mountIsaPrecip === null || townsvillePrecip === null) {
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  console.log(`Threshold (mm): ${thresholdMm}`);
  console.log(`Avg. rainfall near Mount Isa (mm): ${mountIsaPrecip.toFixed(2)}`);
  console.log(`Avg. rainfall near Townsville (mm): ${townsvillePrecip.toFixed(2)}`);

  const mountIsaExceeded = mountIsaPrecip > thresholdMm;
  const townsvilleExceeded = townsvillePrecip > thresholdMm;

  console.log(`Mount Isa exceeded threshold: ${mountIsaExceeded}`);
  console.log(`Townsville exceeded threshold: ${townsvilleExceeded}`);

  if (mountIsaExceeded && townsvilleExceeded) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
